// AppendRunEventParams carries the caller-supplied fields for AppendRunEvent.
// Seq is deliberately absent — the wrapper computes it internally so callers
// never race each other over a caller-chosen sequence number.
type AppendRunEventParams struct {
	RunID     uuid.UUID
	OrgID     uuid.UUID
	EventType string
	Payload   []byte
}

// AppendRunEvent appends one event to run_events with a monotonically
// increasing, gap-free, collision-free seq — even under concurrent callers
// appending to the SAME run.
//
// Each attempt opens its own transaction: it reads the current MAX(seq) for
// the run and inserts at max+1. The UNIQUE(run_id, seq) constraint means a
// racing concurrent attempt that computed the same next seq loses with a
// unique_violation (pgerrcode 23505) rather than corrupting the sequence;
// that failure is caught here and the whole read-then-insert is retried
// with a freshly recomputed max, up to maxAppendRunEventAttempts times. The
// conflict is never surfaced to the caller — AppendRunEvent either succeeds
// with a unique seq or returns an error after exhausting all attempts.
func (r *Repo) AppendRunEvent(ctx context.Context, params AppendRunEventParams) (AgentsRunEvent, error) {
	var out AgentsRunEvent
	for attempt := 0; attempt < maxAppendRunEventAttempts; attempt++ {
		err := r.pool.WithTx(ctx, func(tx pgx.Tx) error {
			q := New(tx)
			maxSeq, err := q.GetMaxRunEventSeq(ctx, params.RunID)
			if err != nil {
				return observability.Wrap(observability.CodeServiceUnavailable, "GetMaxRunEventSeq", err)
			}
			row, err := q.InsertRunEvent(ctx, InsertRunEventParams{
				RunID:     params.RunID,
				OrgID:     params.OrgID,
				Seq:       maxSeq + 1,
				EventType: params.EventType,
				Payload:   params.Payload,
			})
			if err != nil {
				return err
			}
			out = row
			return nil
		})
		if err == nil {
			return out, nil
		}
		if isUniqueViolation(err) {
			// Another concurrent AppendRunEvent won the race for this seq;
			// jitter briefly and retry with a freshly recomputed max+1.
			backoffJitter(attempt)
			continue
		}
		return AgentsRunEvent{}, observability.Wrap(observability.CodeServiceUnavailable, "InsertRunEvent", err)
	}
	return AgentsRunEvent{}, observability.New(observability.CodeServiceUnavailable, "AppendRunEvent: exhausted retries under contention")
}

// isUniqueViolation reports whether err wraps a Postgres unique_violation
// (SQLSTATE 23505), the signal that a concurrent AppendRunEvent call won
// the race for the same (run_id, seq) pair.
func isUniqueViolation(err error) bool {
	var pgErr *pgconn.PgError
	return errors.As(err, &pgErr) && pgErr.Code == uniqueViolation
}

// backoffJitter sleeps a small, attempt-scaled, jittered duration before an
// AppendRunEvent retry, to de-synchronize goroutines that lost the same
// race rather than having them all immediately retry in lockstep.
func backoffJitter(attempt int) {
	base := time.Duration(attempt+1) * time.Millisecond
	jitter := time.Duration(rand.Int63n(int64(time.Millisecond)))
	time.Sleep(base/2 + jitter)
}

