// FinalizeRun atomically updates a run's terminal state (status,
// terminated_reason, tokens_used, iterations_used, elapsed_seconds,
// output_payload) and emits the matching audit-twin + outbox mirror in
// the SAME transaction (mirrors CreateAgent/UpdateAgent's
// emitAgentCreated/emitAgentUpdated pattern). params.TerminatedReason ==
// "completed" emits emitRunCompleted (audit.agents.run.completed);
// every other terminated_reason emits emitRunFailed
// (audit.agents.run.failed). A cross-tenant id (RLS hides the row,
// RETURNING yields nothing) surfaces as NotFound.
func (r *Repo) FinalizeRun(ctx context.Context, params UpdateRunParams) (AgentsAgentRun, error) {
	var out AgentsAgentRun
	err := r.pool.WithTxAsActor(ctx, func(tx pgx.Tx) error {
		row, err := New(tx).UpdateRun(ctx, params)
		if err != nil {
			if errors.Is(err, pgx.ErrNoRows) {
				return observability.New(observability.CodeNotFound, "run not found")
			}
			return observability.Wrap(observability.CodeServiceUnavailable, "UpdateRun", err)
		}
		out = row

		if r.outbox == nil {
			return nil
		}
		if params.TerminatedReason != nil && *params.TerminatedReason == "completed" {
			return r.emitRunCompleted(ctx, tx, row)
		}
		return r.emitRunFailed(ctx, tx, row)
	})
	return out, err
}

