// path plus concurrent contention on the SAME run, exercising the
// unique_violation retry branch that the integration suite also covers.
func TestRepo_AppendRunEvent_SequencesAndLists(t *testing.T) {
	pool := startPostgres(t)
	seedTemplate(t, pool, "tmpl-run-events", "clio", "specialist", []string{"search_documents"})
	r := NewRepo(pool, dbOutboxStub{}, testKeys(t))

	orgID := uuid.New()
	agentID := uuid.New()
	seedTestAgent(t, pool, orgID, agentID, "tmpl-run-events")
	ctx := testCtx(orgID)

	run, err := r.CreateRun(ctx, CreateRunParams{
		OrgID: orgID, AgentID: agentID, UserID: uuid.New(), RunMode: "autonomous", InputPayload: []byte(`{}`),
	})
	require.NoError(t, err)

	ev1, err := r.AppendRunEvent(ctx, AppendRunEventParams{
		RunID: run.ID, OrgID: orgID, EventType: "tool_call", Payload: []byte(`{}`),
	})
	require.NoError(t, err)
	require.Equal(t, int64(1), ev1.Seq)

	const n = 10
	var wg sync.WaitGroup
	errs := make(chan error, n)
	for i := 0; i < n; i++ {
		wg.Add(1)
		go func() {
			defer wg.Done()
			_, err := r.AppendRunEvent(ctx, AppendRunEventParams{
				RunID: run.ID, OrgID: orgID, EventType: "concurrent", Payload: []byte(`{}`),
			})
			errs <- err
		}()
	}
	wg.Wait()
	close(errs)
	for err := range errs {
		require.NoError(t, err)
	}

	events, err := r.ListRunEvents(ctx, run.ID)
	require.NoError(t, err)
	require.Len(t, events, n+1)

	// Cross-tenant: a different org sees no events for this run_id.
	otherEvents, err := r.ListRunEvents(testCtx(uuid.New()), run.ID)
	require.NoError(t, err)
	require.Empty(t, otherEvents)
