package repo

import (
	"testing"

	"github.com/google/uuid"
	"github.com/jackc/pgx/v5"
	"github.com/stretchr/testify/assert"
	"github.com/stretchr/testify/require"
	"google.golang.org/protobuf/proto"

	platformdb "github.com/zenithflowinc/omnicore-platform/platform/libs/go/db"
	auditv1 "github.com/zenithflowinc/omnicore-platform/platform/proto/gen/go/omnicore/audit/v1"
	"github.com/zenithflowinc/omnicore-platform/services/agents-svc/internal/registry"
)

// TestAuditChainLockNamespace_PerOrgDistinctAndStable pins the per-org
// advisory-lock namespace helper: two different orgs must derive DIFFERENT
// namespaces (so their chains serialize independently — a writer in org B
// never blocks org A), the same org must derive a STABLE namespace across
// calls (so concurrent writers of the same org land on the same lock slot),
// and every namespace must carry the schema prefix (so agents' lock slot
// can never collide with another schema's per-org lock in a shared DB).
func TestAuditChainLockNamespace_PerOrgDistinctAndStable(t *testing.T) {
	orgA := uuid.New().String()
	orgB := uuid.New().String()

	nsA := auditChainLockNamespace(orgA)
	nsB := auditChainLockNamespace(orgB)

	assert.NotEqual(t, nsA, nsB, "distinct orgs must derive distinct lock namespaces")
	assert.Equal(t, nsA, auditChainLockNamespace(orgA), "same org must derive a stable namespace")
	assert.Equal(t, "agents.audit_chain:"+orgA, nsA, "namespace must be schema-prefixed and keyed by org id")
}

// auditEventsForOrg fetches every audit.* event_outbox payload for orgID,
// ordered by id ASC (insertion order), decoded back into AuditEvents. The
// read runs under orgID's own tenant context so RLS itself confines the
// result to that org — the ordering across the physical table interleaves
// orgs, but each org sees only its own chain.
func auditEventsForOrg(t *testing.T, pool *platformdb.Pool, orgID uuid.UUID) []*auditv1.AuditEvent {
	t.Helper()
	ctx := testCtx(orgID)
	var out []*auditv1.AuditEvent
	err := pool.WithTx(ctx, func(tx pgx.Tx) error {
		rows, err := tx.Query(ctx,
			`SELECT payload FROM agents.event_outbox
			 WHERE subject LIKE 'audit.%' ORDER BY id ASC`)
		if err != nil {
			return err
		}
		defer rows.Close()
		for rows.Next() {
			var raw []byte
			if err := rows.Scan(&raw); err != nil {
				return err
			}
			ev := &auditv1.AuditEvent{}
			if err := proto.Unmarshal(raw, ev); err != nil {
				return err
			}
			out = append(out, ev)
		}
		return rows.Err()
	})
	require.NoError(t, err)
	return out
}

// TestRepo_PerOrgAuditChain_OrgBWriteDoesNotPerturbOrgA is the core AC#2
// proof for agents-svc: the audit hash chain is PER ORG, not one global
// chain across every tenant.
//
// It interleaves three writes across two orgs — A1, then B1, then A2 — and
// asserts:
//   - A1 is org A's genesis (prev_row_hash == "");
//   - B1 is org B's OWN genesis (prev_row_hash == ""), even though a row
//     (A1) already exists in the table — proving each org starts its own
//     chain rather than linking to whatever row happens to be the global
//     tail;
//   - A2 links to A1 (prev_row_hash == A1.row_hash), NOT to B1 — proving
//     org B's interleaved write did not perturb org A's chain.
//
// Under the old GLOBAL tail read this fails: B1 would chain off A1, and A2
// would chain off B1.
func TestRepo_PerOrgAuditChain_OrgBWriteDoesNotPerturbOrgA(t *testing.T) {
	pool := startPostgres(t)
	seedTemplate(t, pool, "tmpl-perorg-chain", "clio", "specialist", []string{"search_documents"})

	r := NewRepo(pool, dbOutboxStub{}, testKeys(t))
	reg := registry.New(registry.Config{})

	orgA := uuid.New()
	orgB := uuid.New()
	ctxA := testCtx(orgA)
	ctxB := testCtx(orgB)

	_, err := r.CreateAgent(ctxA, reg, CreateAgentInput{TemplateKey: "tmpl-perorg-chain", Name: "A1"})
	require.NoError(t, err)
	_, err = r.CreateAgent(ctxB, reg, CreateAgentInput{TemplateKey: "tmpl-perorg-chain", Name: "B1"})
	require.NoError(t, err)
	_, err = r.CreateAgent(ctxA, reg, CreateAgentInput{TemplateKey: "tmpl-perorg-chain", Name: "A2"})
	require.NoError(t, err)

	eventsA := auditEventsForOrg(t, pool, orgA)
	eventsB := auditEventsForOrg(t, pool, orgB)

	require.Len(t, eventsA, 2, "org A must see exactly its own two audit events")
	require.Len(t, eventsB, 1, "org B must see exactly its own one audit event")

	a1, a2 := eventsA[0], eventsA[1]
	b1 := eventsB[0]

	assert.Equal(t, "", a1.PrevRowHash, "A1 is org A's genesis")
	assert.Equal(t, "", b1.PrevRowHash, "B1 is org B's OWN genesis, not a link off org A's tail")
	assert.Equal(t, a1.RowHash, a2.PrevRowHash, "A2 must link to A1 (org A's tail), unperturbed by org B's interleaved write")
	assert.NotEqual(t, b1.RowHash, a2.PrevRowHash, "A2 must NOT link to org B's row")
}

