// Package repo wraps the sqlc-generated Queries with platform-aware
// transaction handling for agents-svc.
//
// The hand-written constructor is named NewRepo to avoid colliding with
// the sqlc-generated `New(DBTX) *Queries` in this same package. Likewise
// the hand-written parameter types for CreateAgent/UpdateAgent are named
// CreateAgentInput/UpdateAgentInput to avoid colliding with the
// sqlc-generated CreateAgentParams/UpdateAgentParams.
package repo

import (
	"context"
	"errors"
	"math/rand"
	"time"

	"github.com/google/uuid"
	"github.com/jackc/pgx/v5"
	"github.com/jackc/pgx/v5/pgconn"
	"github.com/jackc/pgx/v5/pgtype"
	"google.golang.org/protobuf/proto"
	"google.golang.org/protobuf/types/known/structpb"
	"google.golang.org/protobuf/types/known/timestamppb"

	"github.com/zenithflowinc/omnicore-platform/platform/libs/go/audit"
	"github.com/zenithflowinc/omnicore-platform/platform/libs/go/auth"
	"github.com/zenithflowinc/omnicore-platform/platform/libs/go/db"
	"github.com/zenithflowinc/omnicore-platform/platform/libs/go/observability"
	auditv1 "github.com/zenithflowinc/omnicore-platform/platform/proto/gen/go/omnicore/audit/v1"
	commonv1 "github.com/zenithflowinc/omnicore-platform/platform/proto/gen/go/omnicore/common/v1"
	"github.com/zenithflowinc/omnicore-platform/services/agents-svc/internal/registry"
)

// Budget defaults applied to zero-valued fields on Create/Update (PRD
// issue #1927): a caller that omits a budget field gets these column
// defaults rather than a persisted zero, which would otherwise silently
// starve the executor loop of tokens/iterations/wall-clock/confirmation
// time.
const (
	DefaultTokenBudget             = int32(100000)
	DefaultMaxIterations           = int32(25)
	DefaultMaxWallClockSecs        = int32(300)
	DefaultConfirmationTimeoutSecs = int32(600)
)

// uniqueViolation is the Postgres SQLSTATE for a unique_violation, used by
// AppendRunEvent to detect a racing seq assignment and retry.
const uniqueViolation = "23505"

// maxAppendRunEventAttempts bounds the AppendRunEvent retry loop so a
// pathological amount of contention on the same run fails loudly instead of
// looping forever.
const maxAppendRunEventAttempts = 50

// ErrTemplateNotFound is returned when a template_key does not exist in
// agents.agent_templates.
var ErrTemplateNotFound = errors.New("repo: agent template not found")

// ErrTemplateToolKindViolation is returned when a template's own
// allowed_tools lists a tool that registry.IsToolPermittedForKind
// rejects for the template's kind (e.g. an orchestrator-only tool on a
// "specialist" template). This is a defensive integrity check on the
// template itself, run at every Create and every Update.
var ErrTemplateToolKindViolation = errors.New("repo: agent template allowed_tools violates tool-kind permission")

// Outbox is the minimal interface Repo depends on for event emission.
// *eventbus.Outbox satisfies this interface.
type Outbox interface {
	AddEvent(ctx context.Context, tx pgx.Tx, subject, msgID string, msg proto.Message) error
}

// Repo wraps the platform db.Pool and the sqlc-generated Queries for
// agents-svc: Agent Definitions (Agent Builder save path) and the
// agent_runs/run_events repo layer.
//
// All reads/writes are funneled through db.Pool.WithTx/WithTxAsActor so
// that the `app.current_org_id` GUC is set on every statement. RLS on
// agents.agents, agents.agent_runs, and agents.run_events does the
// cross-tenant isolation.
type Repo struct {
	pool   *db.Pool
	outbox Outbox
	keys   audit.KeyProvider
}

// NewRepo constructs the wrapper. Named NewRepo to avoid colliding with
// the sqlc-generated `New(DBTX) *Queries` in the same package.
// outbox may be nil (e.g. in tests that do not need event emission).
// keys may be nil (in which case audit emission paths return an error at
// runtime — appropriate for read-only test setups that never emit).
func NewRepo(pool *db.Pool, outbox Outbox, keys audit.KeyProvider) *Repo {
	return &Repo{pool: pool, outbox: outbox, keys: keys}
}

// CreateAgentInput carries the caller-supplied fields for CreateAgent —
// mirrors CreateAgentRequest proto fields.
type CreateAgentInput struct {
	TemplateKey             string
	Name                    string
	TokenBudget             int32
	MaxIterations           int32
	MaxWallClockSecs        int32
	ConfirmationTimeoutSecs int32
	AutoWarmContext         bool
	PreResearchMode         bool
	PlanFirstMode           bool
}

// UpdateAgentInput carries the caller-supplied fields for UpdateAgent —
// mirrors UpdateAgentRequest proto fields. There is no TemplateKey field:
// the template is immutable after creation, but UpdateAgent still
// re-validates the agent's EXISTING template_key against
// agents.agent_templates on every save (issue #1927 rule 1 applies to
// "Create AND Update"), so a template deleted or made invalid out from
// under an existing agent is caught here too.
type UpdateAgentInput struct {
	ID                      uuid.UUID
	Name                    string
	TokenBudget             int32
	MaxIterations           int32
	MaxWallClockSecs        int32
	ConfirmationTimeoutSecs int32
	AutoWarmContext         bool
	PreResearchMode         bool
	PlanFirstMode           bool
}

// applyBudgetDefaults replaces any zero-valued budget field with its
// column default in place.
func applyBudgetDefaults(tokenBudget, maxIterations, maxWallClockSecs, confirmationTimeoutSecs *int32) {
	if *tokenBudget == 0 {
		*tokenBudget = DefaultTokenBudget
	}
	if *maxIterations == 0 {
		*maxIterations = DefaultMaxIterations
	}
	if *maxWallClockSecs == 0 {
		*maxWallClockSecs = DefaultMaxWallClockSecs
	}
	if *confirmationTimeoutSecs == 0 {
		*confirmationTimeoutSecs = DefaultConfirmationTimeoutSecs
	}
}

// validateTemplate fetches templateKey from agents.agent_templates
// (404 -> ErrTemplateNotFound) and checks every tool in its own
// allowed_tools against reg via registry.IsToolPermittedForKind — a
// template whose allowed_tools lists a tool not permitted for its own
// kind (or a tool the registry doesn't know about at all) is rejected
// with ErrTemplateToolKindViolation. Runs inside the caller's tx so the
// check and the subsequent write are atomic.
func validateTemplate(ctx context.Context, tx pgx.Tx, reg *registry.Registry, templateKey string) (AgentsAgentTemplate, error) {
	q := New(tx)
	tmpl, err := q.GetAgentTemplateByKey(ctx, templateKey)
	if err != nil {
		if errors.Is(err, pgx.ErrNoRows) {
			return AgentsAgentTemplate{}, ErrTemplateNotFound
		}
		return AgentsAgentTemplate{}, observability.Wrap(observability.CodeServiceUnavailable, "GetAgentTemplateByKey", err)
	}

	for _, toolName := range tmpl.AllowedTools {
		tool, ok := reg.ToolByName(toolName)
		if !ok || !registry.IsToolPermittedForKind(tool, tmpl.Kind) {
			return AgentsAgentTemplate{}, ErrTemplateToolKindViolation
		}
	}
	return tmpl, nil
}

// CreateAgent instantiates a new per-org agent from a template. It
// validates the template (existence + tool-kind integrity) via
// validateTemplate, applies budget defaults to any zero-valued field,
// inserts the row, and — when an outbox is configured — emits a chained
// audit.agents.agent.created twin in the same transaction.
func (r *Repo) CreateAgent(ctx context.Context, reg *registry.Registry, in CreateAgentInput) (AgentsAgent, error) {
	var out AgentsAgent
	err := r.pool.WithTxAsActor(ctx, func(tx pgx.Tx) error {
		if _, err := validateTemplate(ctx, tx, reg, in.TemplateKey); err != nil {
			return err
		}

		h := auth.HeadersFromContext(ctx)
		orgID, err := uuid.Parse(h.TenantID)
		if err != nil {
			return observability.Wrap(observability.CodeForbidden, "invalid tenant id", err)
		}

		id, err := uuid.NewV7()
		if err != nil {
			return observability.Wrap(observability.CodeInternal, "uuid.NewV7 for agent id", err)
		}

		applyBudgetDefaults(&in.TokenBudget, &in.MaxIterations, &in.MaxWallClockSecs, &in.ConfirmationTimeoutSecs)

		q := New(tx)
		row, err := q.CreateAgent(ctx, CreateAgentParams{
			ID:                      id,
			OrgID:                   orgID,
			TemplateKey:             in.TemplateKey,
			Name:                    in.Name,
			TokenBudget:             in.TokenBudget,
			MaxIterations:           in.MaxIterations,
			MaxWallClockSecs:        in.MaxWallClockSecs,
			ConfirmationTimeoutSecs: in.ConfirmationTimeoutSecs,
			AutoWarmContext:         in.AutoWarmContext,
			PreResearchMode:         in.PreResearchMode,
			PlanFirstMode:           in.PlanFirstMode,
		})
		if err != nil {
			return observability.Wrap(observability.CodeServiceUnavailable, "CreateAgent", err)
		}
		out = row

		if r.outbox == nil {
			return nil
		}
		return r.emitAgentCreated(ctx, tx, row)
	})
	return out, err
}

// UpdateAgent mutates the mutable per-agent settings (name + budgets +
// mode flags). It re-validates the agent's EXISTING template_key against
// agents.agent_templates (same rules as CreateAgent — a template deleted
// or made tool-kind-invalid out from under an existing agent is caught
// here), applies budget defaults to any zero-valued field, updates the
// row, and — when an outbox is configured — emits a chained
// audit.agents.agent.updated twin in the same transaction.
//
// Returns AgentsAgent{}, nil (a zero value, no error) when RLS hides the
// row — the caller (handler) maps that to NotFound.
func (r *Repo) UpdateAgent(ctx context.Context, reg *registry.Registry, in UpdateAgentInput) (AgentsAgent, error) {
	var out AgentsAgent
	err := r.pool.WithTxAsActor(ctx, func(tx pgx.Tx) error {
		q := New(tx)
		existing, err := q.GetAgent(ctx, in.ID)
		if err != nil {
			if errors.Is(err, pgx.ErrNoRows) {
				// RLS-hidden or genuinely absent — leave out as the zero
				// value; the handler maps this to NotFound.
				return nil
			}
			return observability.Wrap(observability.CodeServiceUnavailable, "GetAgent", err)
		}

		if _, err := validateTemplate(ctx, tx, reg, existing.TemplateKey); err != nil {
			return err
		}

		applyBudgetDefaults(&in.TokenBudget, &in.MaxIterations, &in.MaxWallClockSecs, &in.ConfirmationTimeoutSecs)

		row, err := q.UpdateAgent(ctx, UpdateAgentParams{
			ID:                      in.ID,
			Name:                    in.Name,
			TokenBudget:             in.TokenBudget,
			MaxIterations:           in.MaxIterations,
			MaxWallClockSecs:        in.MaxWallClockSecs,
			ConfirmationTimeoutSecs: in.ConfirmationTimeoutSecs,
			AutoWarmContext:         in.AutoWarmContext,
			PreResearchMode:         in.PreResearchMode,
			PlanFirstMode:           in.PlanFirstMode,
		})
		if err != nil {
			if errors.Is(err, pgx.ErrNoRows) {
				return nil
			}
			return observability.Wrap(observability.CodeServiceUnavailable, "UpdateAgent", err)
		}
		out = row

		if r.outbox == nil {
			return nil
		}
		return r.emitAgentUpdated(ctx, tx, row)
	})
	return out, err
}

// GetAgent fetches a single agent by id, RLS-scoped to the caller's org.
// Returns AgentsAgent{}, nil (a zero value, no error) when the row is
// absent or hidden by RLS — the caller (handler) maps that to NotFound.
func (r *Repo) GetAgent(ctx context.Context, id uuid.UUID) (AgentsAgent, error) {
	var out AgentsAgent
	err := r.pool.WithTx(ctx, func(tx pgx.Tx) error {
		q := New(tx)
		row, err := q.GetAgent(ctx, id)
		if err != nil {
			if errors.Is(err, pgx.ErrNoRows) {
				return nil
			}
			return observability.Wrap(observability.CodeServiceUnavailable, "GetAgent", err)
		}
		out = row
		return nil
	})
	return out, err
}

// ListAgents returns one page of agents in the caller's org, sorted by
// id (UUIDv7 ≈ creation order). Pass the previous page's last id as
// cursor to fetch the next page; pass uuid.Nil on the first call. limit
// is the maximum number of rows to fetch — the handler fetches limit+1
// to determine whether more pages exist.
func (r *Repo) ListAgents(ctx context.Context, cursor uuid.UUID, limit int32) ([]AgentsAgent, error) {
	var out []AgentsAgent
	err := r.pool.WithTx(ctx, func(tx pgx.Tx) error {
		q := New(tx)
		rows, err := q.ListAgentsPage(ctx, ListAgentsPageParams{
			Column1: pgtype.UUID{Bytes: cursor, Valid: true},
			Limit:   limit,
		})
		if err != nil {
			return observability.Wrap(observability.CodeServiceUnavailable, "ListAgentsPage", err)
		}
		out = rows
		return nil
	})
	return out, err
}

// emitAgentCreated adds an audit.agents.agent.created row to the outbox
// inside the caller's transaction. Mirrors identity-svc's
// emitUserInvited hash-chain pattern: reads the prior row_hash via
// lastRowHash (SELECT ... FOR UPDATE), stamps prev_row_hash/row_hash via
// audit.ChainEvent, then appends through the outbox.
func (r *Repo) emitAgentCreated(ctx context.Context, tx pgx.Tx, a AgentsAgent) error {
	return r.emitAgentTwin(ctx, tx, a, "agents.agent.created", "audit.agents.agent.created")
}

// emitAgentUpdated adds an audit.agents.agent.updated row to the outbox
// inside the caller's transaction. Mirrors emitAgentCreated.
func (r *Repo) emitAgentUpdated(ctx context.Context, tx pgx.Tx, a AgentsAgent) error {
	return r.emitAgentTwin(ctx, tx, a, "agents.agent.updated", "audit.agents.agent.updated")
}

func (r *Repo) emitAgentTwin(ctx context.Context, tx pgx.Tx, a AgentsAgent, action, subject string) error {
	h := auth.HeadersFromContext(ctx)

	eventID, err := uuid.NewV7()
	if err != nil {
		return observability.Wrap(observability.CodeInternal, "uuid.NewV7 for event_id", err)
	}

	payload, err := structpb.NewStruct(map[string]any{
		"agent_id":     a.ID.String(),
		"template_key": a.TemplateKey,
		"name":         a.Name,
	})
	if err != nil {
		return observability.Wrap(observability.CodeInternal, "build audit payload", err)
	}

	event := &auditv1.AuditEvent{
		EventId:       eventID.String(),
		EmittedAt:     timestamppb.New(time.Now()),
		SourceService: "agents-svc",
		Action:        action,
		ActorOrg:      &commonv1.OrgID{Value: a.OrgID.String()},
		TargetType:    "agent",
		TargetId:      a.ID.String(),
		Payload:       payload,
	}
	if h.UserID != "" {
		event.Actor = &auditv1.AuditEvent_ActorUser{ActorUser: &commonv1.UserID{Value: h.UserID}}
	}
	if h.RequestID != "" {
		event.RequestId = &commonv1.RequestID{Value: h.RequestID}
	}

	// Source the per-org chain key from the event's own ActorOrg — the same
	// value the outbox INSERT's org_id DEFAULT stamps from the tx GUC, and
	// the same value the verifier reads to walk this org's chain.
	prev, err := r.lastRowHash(ctx, tx, event.GetActorOrg().GetValue())
	if err != nil {
		return err
	}
	if r.keys == nil {
		return observability.New(observability.CodeInternal, "audit emission requires KeyProvider; pass one to repo.NewRepo")
	}
	keyID, key := r.keys.ActiveKey()
	if err := audit.ChainEvent(event, prev, keyID, key); err != nil {
		return observability.Wrap(observability.CodeInternal, "audit.ChainEvent", err)
	}

	return r.outbox.AddEvent(ctx, tx, subject, eventID.String(), event)
}

// auditChainLockNamespace returns the stable, per-org advisory-lock
// namespace string for agents-svc's audit hash chain. It is namespaced by
// schema ("agents.audit_chain:") so agents' lock slot never collides with
// another schema's per-org lock if the two ever share a database, and keyed
// by orgID so each tenant's chain serializes independently — a write in
// org B never blocks (or forks) org A's chain. The returned string is fed
// to Postgres hashtextextended(<ns>, 0) to derive the bigint key that
// pg_advisory_xact_lock takes; deriving the key in SQL (rather than in Go)
// keeps it identical to the org-svc/identity-svc per-org lock convention.
func auditChainLockNamespace(orgID string) string {
	return "agents.audit_chain:" + orgID
}

// lastRowHash fetches the row_hash of the tail of the PER-ORG audit hash
// chain for orgID, within the caller's transaction, so the next event can
// link its prev_row_hash to it. agents.event_outbox holds one interleaved
// chain per org (partitioned by the org_id column added in migration
// 00006); each org's chain has its own genesis, so the tail read is scoped
// `WHERE org_id = $1` — reading the GLOBAL tail (as this did before #2394)
// would chain a new tenant's genesis off whatever other tenant's row
// happened to be last, exposing one org's row_hash to another and breaking
// the per-org verifier walk.
//
// A PER-ORG pg_advisory_xact_lock (keyed by auditChainLockNamespace) is
// taken BEFORE the tail SELECT and is the SOLE serializer of concurrent
// writers of the same org's chain, in both the empty-chain case (a plain
// tail read that matches zero rows takes no row lock, so two txs could each
// read an empty tail and insert sibling genesis rows) and the
// one-past-genesis case (under READ COMMITTED a blocking row lock does not
// re-scan for a new tail once unblocked). It is per-org so writers in
// different tenants never contend.
//
// The tail SELECT deliberately does NOT use FOR UPDATE: migration 00006
// revokes UPDATE on agents.event_outbox from agents_app (closing the
// audit-row tamper vector — only the BYPASSRLS agents_drainer may UPDATE,
// to mark rows published), and Postgres requires the UPDATE privilege to
// take a FOR UPDATE row lock, so FOR UPDATE here would fail with SQLSTATE
// 42501 under the app role. FOR UPDATE was only ever defense-in-depth on
// top of the advisory lock (which does the real serialization), so dropping
// it costs no correctness.
//
// orgID MUST equal the app.current_org_id GUC the INSERT's org_id DEFAULT
// stamps (both derive from the AuditEvent's ActorOrg at the call site), so
// lock scope, read scope, and the RLS-enforced write scope can never
// diverge.
//
// If tx is nil (e.g. in unit tests without a real DB), it returns
// ("", nil) so the first event in the chain starts with an empty
// prev_row_hash. If no rows exist yet for orgID, it also returns ("", nil)
// — that org's genesis.
func (r *Repo) lastRowHash(ctx context.Context, tx pgx.Tx, orgID string) (string, error) {
	if tx == nil {
		return "", nil
	}
	// An empty org id would make the advisory-lock namespace and the
	// `$1::uuid` tail-read predicate degenerate — the cast raises SQLSTATE
	// 22P02 (invalid_text_representation) and crashes the emit. A
	// state-changing audit emit with no tenant is a bug, not a valid
	// genesis, so fail loudly rather than forge a global-tail read. Mirrors
	// identity-svc's lastRowHash guard.
	if orgID == "" {
		return "", observability.New(observability.CodeInternal,
			"lastRowHash requires a non-empty org id to scope the per-org audit chain")
	}

	// Per-org advisory lock, held for the rest of the tx.
	if _, err := tx.Exec(ctx,
		`SELECT pg_advisory_xact_lock(hashtextextended($1, 0))`,
		auditChainLockNamespace(orgID),
	); err != nil {
		return "", observability.Wrap(observability.CodeInternal, "lastRowHash advisory lock", err)
	}

	var rawPayload []byte
	err := tx.QueryRow(ctx,
		`SELECT payload FROM agents.event_outbox WHERE org_id = $1::uuid ORDER BY id DESC LIMIT 1`,
		orgID,
	).Scan(&rawPayload)
	if err != nil {
		if errors.Is(err, pgx.ErrNoRows) {
			return "", nil
		}
		return "", observability.Wrap(observability.CodeInternal, "lastRowHash query", err)
	}

	var prev auditv1.AuditEvent
	if err := proto.Unmarshal(rawPayload, &prev); err != nil {
		return "", observability.Wrap(observability.CodeInternal, "lastRowHash unmarshal", err)
	}
	return prev.RowHash, nil
}

// CreateRun inserts a new agent_runs row, emits its audit.agents.run.started
// twin in the same transaction (so a run that never reaches a terminal
// state — crash, or indefinite awaiting_confirmation — still leaves an
// audit trail that it was started), and returns the post-image. RLS's
// WITH CHECK on INSERT rejects an org_id argument that doesn't match the
// caller's tenant (set via the WithTx GUC) rather than silently accepting it.
func (r *Repo) CreateRun(ctx context.Context, params CreateRunParams) (AgentsAgentRun, error) {
	var out AgentsAgentRun
	err := r.pool.WithTxAsActor(ctx, func(tx pgx.Tx) error {
		row, err := New(tx).CreateRun(ctx, params)
		if err != nil {
			return observability.Wrap(observability.CodeServiceUnavailable, "CreateRun", err)
		}
		out = row

		if r.outbox == nil {
			return nil
		}
		return r.emitRunStarted(ctx, tx, row)
	})
	return out, err
}

// emitRunStarted adds an audit.agents.run.started row to the outbox inside
// the caller's transaction. Mirrors emitRunCompleted/emitRunFailed.
func (r *Repo) emitRunStarted(ctx context.Context, tx pgx.Tx, run AgentsAgentRun) error {
	return r.emitRunTwin(ctx, tx, run, "agents.run.started", "audit.agents.run.started")
}

// GetRun fetches a single run by id, scoped to the caller's tenant via RLS.
