			}
			return observability.Wrap(observability.CodeServiceUnavailable, "GetAgentTemplateByKey", err)
		}
		out = row
		return nil
	})
	return out, err
}

// FinalizeRun atomically updates a run's terminal state (status,
// terminated_reason, tokens_used, iterations_used, elapsed_seconds,
// output_payload) and emits the matching audit-twin + outbox mirror in
// the SAME transaction (mirrors CreateAgent/UpdateAgent's
// emitAgentCreated/emitAgentUpdated pattern). params.TerminatedReason ==
// "completed" emits emitRunCompleted (audit.agents.run.completed);
// every other terminated_reason emits emitRunFailed
// (audit.agents.run.failed). A cross-tenant id (RLS hides the row,
// RETURNING yields nothing) surfaces as NotFound.
func (r *Repo) FinalizeRun(ctx context.Context, params UpdateRunParams) (AgentsAgentRun, error) {
	var out AgentsAgentRun
	err := r.pool.WithTxAsActor(ctx, func(tx pgx.Tx) error {
		row, err := New(tx).UpdateRun(ctx, params)
		if err != nil {
			if errors.Is(err, pgx.ErrNoRows) {
				return observability.New(observability.CodeNotFound, "run not found")
			}
			return observability.Wrap(observability.CodeServiceUnavailable, "UpdateRun", err)
		}
		out = row

		if r.outbox == nil {
			return nil
		}
		if params.TerminatedReason != nil && *params.TerminatedReason == "completed" {
			return r.emitRunCompleted(ctx, tx, row)
		}
		return r.emitRunFailed(ctx, tx, row)
	})
	return out, err
}

// emitRunCompleted adds an audit.agents.run.completed row to the outbox
// inside the caller's transaction. Mirrors emitAgentCreated.
func (r *Repo) emitRunCompleted(ctx context.Context, tx pgx.Tx, run AgentsAgentRun) error {
	return r.emitRunTwin(ctx, tx, run, "agents.run.completed", "audit.agents.run.completed")
}

// emitRunFailed adds an audit.agents.run.failed row to the outbox inside
// the caller's transaction. Used for every terminated_reason other than
// "completed" (budget_exceeded, iteration_cap, time_cap, error, etc).
func (r *Repo) emitRunFailed(ctx context.Context, tx pgx.Tx, run AgentsAgentRun) error {
	return r.emitRunTwin(ctx, tx, run, "agents.run.failed", "audit.agents.run.failed")
}

func (r *Repo) emitRunTwin(ctx context.Context, tx pgx.Tx, run AgentsAgentRun, action, subject string) error {
	h := auth.HeadersFromContext(ctx)

	eventID, err := uuid.NewV7()
	if err != nil {
		return observability.Wrap(observability.CodeInternal, "uuid.NewV7 for event_id", err)
	}

	terminatedReason := ""
	if run.TerminatedReason != nil {
		terminatedReason = *run.TerminatedReason
	}
	payload, err := structpb.NewStruct(map[string]any{
		"run_id":            run.ID.String(),
		"agent_id":          run.AgentID.String(),
		"status":            run.Status,
		"terminated_reason": terminatedReason,
		"tokens_used":       float64(run.TokensUsed),
		"iterations_used":   float64(run.IterationsUsed),
	})
	if err != nil {
		return observability.Wrap(observability.CodeInternal, "build audit payload", err)
	}

	event := &auditv1.AuditEvent{
		EventId:       eventID.String(),
		EmittedAt:     timestamppb.New(time.Now()),
		SourceService: "agents-svc",
		Action:        action,
		ActorOrg:      &commonv1.OrgID{Value: run.OrgID.String()},
		TargetType:    "run",
		TargetId:      run.ID.String(),
		Payload:       payload,
	}
	if h.UserID != "" {
		event.Actor = &auditv1.AuditEvent_ActorUser{ActorUser: &commonv1.UserID{Value: h.UserID}}
	}
	if h.RequestID != "" {
		event.RequestId = &commonv1.RequestID{Value: h.RequestID}
	}

	// Source the per-org chain key from the event's own ActorOrg — the same
	// value the outbox INSERT's org_id DEFAULT stamps from the tx GUC, and
	// the same value the verifier reads to walk this org's chain.
	prev, err := r.lastRowHash(ctx, tx, event.GetActorOrg().GetValue())
	if err != nil {
		return err
	}
	if r.keys == nil {
		return observability.New(observability.CodeInternal, "audit emission requires KeyProvider; pass one to repo.NewRepo")
	}
	keyID, key := r.keys.ActiveKey()
	if err := audit.ChainEvent(event, prev, keyID, key); err != nil {
		return observability.Wrap(observability.CodeInternal, "audit.ChainEvent", err)
	}

	return r.outbox.AddEvent(ctx, tx, subject, eventID.String(), event)
}

// ListRunEvents returns every event for run_id in seq order, scoped to the
// caller's tenant via RLS. A cross-tenant run_id yields an empty slice
// rather than an error, since the run's non-existence in this tenant is a
// legitimate empty result (mirrors GetRun's cross-tenant test elsewhere,
// which instead treats absence as NotFound at the single-row level).
func (r *Repo) ListRunEvents(ctx context.Context, runID uuid.UUID) ([]AgentsRunEvent, error) {
	var out []AgentsRunEvent
	err := r.pool.WithTx(ctx, func(tx pgx.Tx) error {
		rows, err := New(tx).ListRunEvents(ctx, runID)
		if err != nil {
			return observability.Wrap(observability.CodeServiceUnavailable, "ListRunEvents", err)
		}
		out = rows
		return nil
	})
	return out, err
}

// ListRunEventsAfterSeq returns every event for run_id with seq strictly
// greater than afterSeq, in seq order, scoped to the caller's tenant via
// RLS. Used by StreamRunEvents' poll loop so a re-poll only transfers
// events past the client's last-seen seq, rather than the whole history
// every tick. A cross-tenant run_id yields an empty slice, matching
// ListRunEvents.
func (r *Repo) ListRunEventsAfterSeq(ctx context.Context, runID uuid.UUID, afterSeq int64) ([]AgentsRunEvent, error) {
	var out []AgentsRunEvent
	err := r.pool.WithTx(ctx, func(tx pgx.Tx) error {
		rows, err := New(tx).ListRunEventsAfterSeq(ctx, ListRunEventsAfterSeqParams{
			RunID: runID,
			Seq:   afterSeq,
		})
		if err != nil {
			return observability.Wrap(observability.CodeServiceUnavailable, "ListRunEventsAfterSeq", err)
		}
		out = rows
		return nil
	})
	return out, err
}


