// dbOutboxStub writes events directly to agents.event_outbox inside the
// caller's transaction, satisfying Outbox without a NATS connection.
type dbOutboxStub struct{}

func (dbOutboxStub) AddEvent(ctx context.Context, tx pgx.Tx, subject, msgID string, msg proto.Message) error {
	body, err := proto.Marshal(msg)
	if err != nil {
		return err
	}
	_, err = tx.Exec(ctx,
		`INSERT INTO agents.event_outbox (subject, msg_id, payload) VALUES ($1, $2, $3) ON CONFLICT (msg_id) DO NOTHING`,
		subject, msgID, body,
	)
	return err
}

func testKeys(t *testing.T) audit.KeyProvider {
	t.Helper()
	p, err := audit.NewEnvKeyProvider("test-v1:dGVzdC1hZ2VudHMtYXVkaXQtaG1hYy1rZXktMzItYiEh", "test-v1")
	require.NoError(t, err)
	return p
}

// startPostgres boots a fresh Postgres testcontainer, runs goose migrations,
// and returns a *platformdb.Pool connected as the agents_app role. Callers
// skip this in short mode implicitly via the testcontainers startup cost.
func startPostgres(t *testing.T) *platformdb.Pool {
	t.Helper()
	if testing.Short() {
		t.Skip("skipping repo test in short mode")
	}
	ctx := context.Background()
	pgC, err := postgres.Run(ctx,
		"postgres:16.4-alpine",
		postgres.WithDatabase("agents_repo_test"),
		postgres.WithUsername("postgres"),
		postgres.WithPassword("test"),
		testcontainers.WithWaitStrategy(
			wait.ForLog("database system is ready to accept connections").
				WithOccurrence(2).
				WithStartupTimeout(60*time.Second),
		),
	)
	require.NoError(t, err)
	t.Cleanup(func() { _ = pgC.Terminate(ctx) })

	dsn, err := pgC.ConnectionString(ctx, "sslmode=disable")
	require.NoError(t, err)

	_, file, _, _ := runtime.Caller(0)
	migrationsDir := filepath.Join(filepath.Dir(file), "..", "..", "migrations")

	gooseDB, err := goose.OpenDBWithDriver("pgx", dsn)
	require.NoError(t, err)
	require.NoError(t, goose.SetDialect("postgres"))
	goose.SetTableName("goose_db_version_agents")
	require.NoError(t, goose.Up(gooseDB, migrationsDir))

	_, err = gooseDB.Exec(`ALTER ROLE agents_app WITH LOGIN PASSWORD 'test_app'`)
	require.NoError(t, err)
	require.NoError(t, gooseDB.Close())

	u, err := url.Parse(dsn)
	require.NoError(t, err)
	u.User = url.UserPassword("agents_app", "test_app")

	pool, err := platformdb.NewPool(ctx, u.String())
	require.NoError(t, err)
	t.Cleanup(pool.Close)
	return pool
}

