// TestRepo_CreateRun_EmitsRunStartedTwin proves CreateRun's audit twin: a
// run that never reaches a terminal state (crash, or indefinite
// awaiting_confirmation) still leaves an audit.agents.run.started row in
// the outbox, rather than zero audit trail that it was ever started.
func TestRepo_CreateRun_EmitsRunStartedTwin(t *testing.T) {
	pool := startPostgres(t)
	seedTemplate(t, pool, "tmpl-run-started", "clio", "specialist", []string{"search_documents"})
	r := NewRepo(pool, dbOutboxStub{}, testKeys(t))

	orgID, agentID := uuid.New(), uuid.New()
	seedTestAgent(t, pool, orgID, agentID, "tmpl-run-started")
	ctx := testCtx(orgID)

	run, err := r.CreateRun(ctx, CreateRunParams{
		OrgID: orgID, AgentID: agentID, UserID: uuid.New(), RunMode: "autonomous", InputPayload: []byte(`{}`),
	})
	require.NoError(t, err)

	var count int
	err = pool.WithTx(ctx, func(tx pgx.Tx) error {
		return tx.QueryRow(ctx,
			`SELECT count(*) FROM agents.event_outbox WHERE subject = $1`,
			"audit.agents.run.started",
		).Scan(&count)
	})
	require.NoError(t, err)
	assert.Equal(t, 1, count)

	// No outbox configured -> CreateRun still inserts the row but skips
	// audit emission entirely.
	noOutboxRepo := NewRepo(pool, nil, nil)
	run2, err := noOutboxRepo.CreateRun(ctx, CreateRunParams{
		OrgID: orgID, AgentID: agentID, UserID: uuid.New(), RunMode: "autonomous", InputPayload: []byte(`{}`),
	})
	require.NoError(t, err)
	assert.NotEqual(t, uuid.Nil, run2.ID)
	assert.NotEqual(t, run.ID, run2.ID)
}

