// TestRepo_PauseThenResumeRunForConfirmation drives the HITL pause/resume
// pair added for issue #1929 against a real Postgres.
func TestRepo_PauseThenResumeRunForConfirmation(t *testing.T) {
	pool := startPostgres(t)
	seedTemplate(t, pool, "tmpl-repo-pause", "clio", "specialist", []string{"search_documents"})

	r := NewRepo(pool, dbOutboxStub{}, testKeys(t))
	orgID := uuid.New()
	agentID := uuid.New()
	seedTestAgent(t, pool, orgID, agentID, "tmpl-repo-pause")
	ctx := tenantCtx(orgID.String(), uuid.New().String())

	run, err := r.CreateRun(ctx, CreateRunParams{
		OrgID: orgID, AgentID: agentID, UserID: uuid.New(), RunMode: "autonomous", InputPayload: []byte(`{}`),
	})
	require.NoError(t, err)

	pending := []byte(`{"tool_name":"delete_file","args":{},"tokens_used":1,"paused_at":"2026-01-01T00:00:00Z"}`)
	paused, err := r.PauseRunForConfirmation(ctx, run.ID, pending)
	require.NoError(t, err)
	assert.Equal(t, "awaiting_confirmation", paused.Status)
	assert.True(t, paused.AwaitingConfirmation)
	assert.JSONEq(t, string(pending), string(paused.PendingCall))

	resumed, err := r.ResumeRunAfterConfirmation(ctx, run.ID)
	require.NoError(t, err)
	assert.Equal(t, "running", resumed.Status)
	assert.False(t, resumed.AwaitingConfirmation)
	assert.Nil(t, resumed.PendingCall)
}

